def solve(path: str) -> str:
    """Simplify a Unix-style path.
    Handles both absolute and relative paths robustly.
    """
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # if relative and cannot go up, keep '..'
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(part)
    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
    else:
        return '/'.join(stack) if stack else '.'

