def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes with O(n log log n) time.
    Handles any non‑negative integer n; for n <= 2 the answer is 0.
    """
    # Ensure n is an integer
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Boolean array where index i indicates primality of i
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    limit = int(n ** 0.5) + 1
    for i in range(2, limit):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False
    return sum(is_prime)

