def solve(s):
    """Return the length of the longest substring of s with no repeated
    characters (sliding window)."""
    best = 0
    start = 0
    last_seen = {}
    for i, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        best = max(best, i - start + 1)
    return best

