def solve(path: str) -> str:
    # Simplify Unix-style path, handling both absolute and relative inputs.
    # For absolute paths (starting with '/'), result always starts with '/'.
    # For relative paths, result does not start with '/' and empty result is '.'.
    is_abs = path.startswith('/')
    # Split by '/', keep empty strings to handle leading/trailing slashes.
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # At root (absolute) ignore, at relative preserve '..'
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(part)
    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
    else:
        return '/'.join(stack) if stack else '.'

