def solve(s):
    """Convert a Roman numeral to an integer.
    Handles standard numerals with subtractive notation.
    """
    values = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    i = 0
    while i < len(s):
        # If a smaller value precedes a larger one, it's subtractive.
        if i+1 < len(s) and values[s[i]] < values[s[i+1]]:
            total += values[s[i+1]] - values[s[i]]
            i += 2
        else:
            total += values[s[i]]
            i += 1
    return total

