from bisect import bisect_left

def solve(nums):
    """Return the length of the longest strictly increasing subsequence."""
    if not nums:
        return 0
    tails = []
    for x in nums:
        pos = bisect_left(tails, x)
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
