def solve(coins, amount) -> int:
    coins = sorted(coins, reverse=True)
    count = 0
    remaining = amount
    for c in coins:
        if remaining <= 0:
            break
        k = remaining // c
        count += k
        remaining -= k * c
    if remaining != 0:
        return -1
    return count

