def solve(a, x):
    """Return the smallest index at which x could be inserted into sorted
    list a while keeping it sorted (leftmost insertion point)."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

